let
    Demo = Binary.Decompress(Binary.FromText("", BinaryEncoding.Base64), Compression.Deflate),
    Source = if DataMode = "Demo" then Demo else if DataMode = "Folder" then File.Contents(DataFolder & "/Trading.csv") else error "DataMode must be Demo or Folder",
    Parsed = Csv.Document(Source, [Delimiter=",", Encoding=65001, QuoteStyle=QuoteStyle.Csv]),
    Headers = Table.PromoteHeaders(Parsed, [PromoteAllScalars=true]),
    Typed = Table.TransformColumnTypes(Headers, {{"StoreDayID", type text}, {"StoreID", type text}, {"Date", type date}, {"Visitors", Int64.Type}, {"Transactions", Int64.Type}, {"Units", Int64.Type}, {"GrossSales", Currency.Type}, {"Refunds", Currency.Type}, {"NetCOGS", Currency.Type}, {"Target", Currency.Type}}, "en-US")
in
    Typed
